760	// Store is a persistent workbench backed by one local data directory.
761	//
762	// All operations are safe for concurrent use by multiple goroutines and by
763	// several processes pointed at the same directory: an in-process mutex plus a
764	// process-shared flock serialize commits, and every commit is an atomic
765	// temp-file/fsync/rename replacement. Open the directory with Open and call
766	// Close when done.
767	type Store struct {
768		dir  string
769		mu   sync.Mutex
770		lock *os.File
771	
772		data envelope
773	}
774	
775	// Open opens (creating if needed) the workbench data in dir. If the
776	// directory does not exist it is created. Existing committed data is loaded
777	// and fully validated before Open returns; on a corrupt, truncated or
778	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
779	// leaves every file in the directory untouched.
780	func Open(dir string) (*Store, error) {
781		if dir == "" {
782			return nil, invalidf("data directory must not be empty")
783		}
784		if err := os.MkdirAll(dir, 0o755); err != nil {
785			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
786		}
787		lockPath := filepath.Join(dir, dirLockFile)
788		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
789		if err != nil {
790			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
791		}
792		// Serialize against other processes while we read / validate.
793		if err := lockExclusive(lock); err != nil {
794			lock.Close()
795			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
796		}
797	
798		s := &Store{dir: dir, lock: lock}
799		if err := s.loadLocked(); err != nil {
800			unlockLock(lock)
801			lock.Close()
802			return nil, err
803		}
804		// The lock is taken again per operation; holding it for the store's
805		// lifetime would forbid two open handles on one directory.
806		if err := unlockLock(lock); err != nil {
807			lock.Close()
808			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
809		}
810		return s, nil
811	}
812	
813	// Close releases the directory lock. It does not discard committed data.
814	func (s *Store) Close() error {
815		s.mu.Lock()
816		defer s.mu.Unlock()
817		if s.lock == nil {
818			return nil
819		}
820		var first error
821		if err := unlockLock(s.lock); err != nil {
822			first = err
823		}
824		if err := s.lock.Close(); err != nil && first == nil {
825			first = err
826		}
827		s.lock = nil
828		return first
829	}
830	
831	// Dir reports the data directory backing the store.
832	func (s *Store) Dir() string { return s.dir }
833	
834	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
835	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
836	
837	// loadLocked reads and validates the committed file. Caller must hold the
838	// exclusive flock; the in-process mutex is taken by the public Open path.
839	func (s *Store) loadLocked() error {
840		raw, err := os.ReadFile(s.dataPath())
841		if errors.Is(err, os.ErrNotExist) {
842			s.data = envelope{Format: FormatVersion}
843			return nil
844		}
845		if err != nil {
846			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
847		}
848		if len(strings.TrimSpace(string(raw))) == 0 {
849			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
850		}
851	
852		var env envelope
853		if err := json.Unmarshal(raw, &env); err != nil {
854			// Shape failures surfaced by the persisted-definition decoders are
855			// integrity failures, not JSON syntax errors; report their detail
856			// instead of the generic "not valid JSON" wording.
857			var se StoreError
858			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
859				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
860			}
861			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
862		}
863		if env.Format == 0 {
864			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
865		}
866		if env.Format != FormatVersion {
867			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
868				s.dataPath(), env.Format, FormatVersion)
869		}
870		if err := validateEnvelope(env); err != nil {
871			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
872		}
873		s.data = env
874		return nil
875	}
876	
877	// commitLocked writes the pending state atomically: temp file → fsync →
878	// rename → fsync directory. Caller must hold both the in-process mutex and
879	// the exclusive flock; all in-memory mutations must already have happened and
880	// been rule-checked, so a failure here occurs before any success is reported.
881	func (s *Store) commitLocked() error {
882		s.data.Format = FormatVersion
883		// Stable output: records are stored sorted so files are deterministic.
884		sortEnvelope(&s.data)
885	
886		payload, err := json.MarshalIndent(&s.data, "", "  ")
887		if err != nil {
888			return fmt.Errorf("cannot encode data: %w", err)
889		}
890		payload = append(payload, '\n')
891	
892		tmp := s.tmpPath()
893		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
894		if err != nil {
895			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
896		}
897		if _, err := f.Write(payload); err != nil {
898			f.Close()
899			os.Remove(tmp)
900			return fmt.Errorf("cannot write staged data: %w", err)
901		}
902		if err := f.Sync(); err != nil {
903			f.Close()
904			os.Remove(tmp)
905			return fmt.Errorf("cannot flush staged data: %w", err)
906		}
907		if err := f.Close(); err != nil {
908			os.Remove(tmp)
909			return fmt.Errorf("cannot finish staged data: %w", err)
910		}
911		if err := os.Rename(tmp, s.dataPath()); err != nil {
912			os.Remove(tmp)
913			return fmt.Errorf("cannot commit data file: %w", err)
914		}
915		if err := syncDir(s.dir); err != nil {
916			// The rename already happened; lack of dir fsync only weakens crash
917			// durability, never correctness of what is visible now.
918			return nil
919		}
920		return nil
921	}
922	
923	// withLock runs fn under the in-process mutex and an exclusive flock, then
924	// atomically commits when fn requests it. The on-disk state is re-read after
925	// acquiring the lock, so concurrent commits from another process or another
926	// handle are always observed. Operations validate before mutating; a rejected
927	// operation (commit=false or an error) writes nothing and leaves committed
928	// state unchanged.
929	func (s *Store) withLock(fn func() (commit bool, err error)) error {
930		s.mu.Lock()
931		defer s.mu.Unlock()
932		if s.lock == nil {
933			return invalidf("store is closed")
934		}
935		if err := lockExclusive(s.lock); err != nil {
936			return fmt.Errorf("cannot lock data directory: %w", err)
937		}
938		defer unlockLock(s.lock)
939	
940		if err := s.loadLocked(); err != nil {
941			return err
942		}
943		commit, err := fn()
944		if err != nil {
945			return err
946		}
947		if !commit {
948			return nil
949		}
950		return s.commitLocked()
951	}
952	
953	// withLockRead runs fn under a shared flock over freshly reloaded state.
954	func (s *Store) withLockRead(fn func() error) error {
955		s.mu.Lock()
956		defer s.mu.Unlock()
957		if s.lock == nil {
958			return invalidf("store is closed")
959		}
960		if err := lockShared(s.lock); err != nil {
961			return fmt.Errorf("cannot lock data directory: %w", err)
962		}
963		defer unlockLock(s.lock)
964		if err := s.loadLocked(); err != nil {
965			return err
966		}
967		return fn()
968	}
