992	// validateEnvelope re-checks every invariant on load so a tampered or
993	// hand-edited file cannot bypass the domain rules.
994	func validateEnvelope(env envelope) error {
995		seenCircuit := make(map[[2]string]bool)
996		circuitOK := make(map[[2]string]bool)
997		for i, c := range env.Circuits {
998			key := [2]string{c.Name, itoa(c.Version)}
999			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
1000				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
1001			}
1002			if c.Version <= 0 {
1003				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
1004			}
1005			if seenCircuit[key] {
1006				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
1007			}
1008			seenCircuit[key] = true
1009			if c.Constraints <= 0 {
1010				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
1011			}
1012			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
1013				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
1014			}
1015			// The same representability rule the write path enforces: wire 0 plus
1016			// every declared input must fit inside the platform's int. A record
1017			// beyond that bound can never have been written by this build and
1018			// cannot be checked safely, so the directory is corrupt rather than
1019			// silently narrowed or read with a wrapped-around layout.
1020			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
1021				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
1022					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
1023			}
1024			if c.Definition != nil {
1025				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
1026					return err
1027				}
1028			}
1029			circuitOK[key] = true
1030		}
1031		seenSetup := make(map[[2]string]bool)
1032		for i, p := range env.Setups {
1033			key := [2]string{p.Name, itoa(p.Version)}
1034			if !circuitOK[key] {
1035				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
1036			}
1037			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
1038			if c == nil || !c.Frozen {
1039				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
1040			}
1041			if seenSetup[key] {
1042				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
1043			}
1044			seenSetup[key] = true
1045		}
1046		seenJob := make(map[string]bool)
1047		for i, j := range env.Jobs {
1048			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
1049				return fmt.Errorf("job #%d has an empty or blank id", i+1)
1050			}
1051			if seenJob[j.ID] {
1052				return fmt.Errorf("job %q appears more than once", j.ID)
1053			}
1054			seenJob[j.ID] = true
1055			if j.Kind != "prove" {
1056				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
1057			}
1058			if j.Attempt <= 0 {
1059				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
1060			}
1061			key := [2]string{j.Circuit, itoa(j.Version)}
1062			if !circuitOK[key] {
1063				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
1064			}
1065			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
1066			if c == nil || !c.Frozen {
1067				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
1068			}
1069			if !seenSetup[key] {
1070				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
1071			}
1072			// A recorded compiled-artifact binding must still resolve against the
1073			// pinned version's artifact; a dangling or mismatched binding makes
1074			// the file unreadable rather than silently dropping the binding.
1075			if j.CompiledHash != "" {
1076				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
1077				if artifact == nil {
1078					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
1079				}
1080				if artifact.Hash != j.CompiledHash {
1081					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
1082						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
1083				}
1084			}
1085		}
1086		seenArtifact := make(map[[2]string]bool)
1087		for i, a := range env.Artifacts {
1088			key := [2]string{a.Name, itoa(a.Version)}
1089			if !circuitOK[key] {
1090				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
1091			}
1092			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
1093			if c == nil || !c.Frozen {
1094				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
1095			}
1096			if seenArtifact[key] {
1097				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
1098			}
1099			seenArtifact[key] = true
1100			if c.Definition == nil {
1101				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1102			}
1103			if a.Constraints != c.Constraints {
1104				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1105					a.Name, a.Version, a.Constraints, c.Constraints)
1106			}
1107			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1108			if err != nil {
1109				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1110			}
1111			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1112				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1113			}
1114			wantHash := artifactHash(a.Name, a.Version, def)
1115			if a.Hash != wantHash {
1116				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1117					a.Name, a.Version, a.Hash, wantHash)
1118			}
1119		}
1120		return nil
1121	}
