1	package zkcircuit
2	
3	import (
4		"errors"
5		"strconv"
6		"strings"
7		"testing"
8	)
9	
10	// Regression tests for a non-ASCII lookalike spelling of the compiled-artifact
11	// binding field. encoding/json matches struct tags with Unicode case folding,
12	// under which "compiled_haſh" (U+017F long s, written directly or as the
13	// JSON escape u017f) fills CompiledHash exactly like "compiled_hash". The
14	// binding field only accepts the canonical spelling and its ASCII case
15	// variants, so such a lookalike is data corruption: it must not be ignored
16	// as an unknown member (which would read a bound job as unbound and drop the
17	// field on the next commit), whatever its value, even with a legal hash or
18	// an explicit "", and even beside a correctly spelled key in either order
19	// and with agreeing values.
20	
21	// longS is U+017F (Latin small letter long s), the only non-ASCII rune whose
22	// fold set intersects compiled_hash.
23	const longS = "ſ"
24	
25	// lookalikeKey is "compiled_haſh" with the long s.
26	var lookalikeKey = "compiled_ha" + longS + "h"
27	
28	// jsonEscapePrefix is one literal backslash, used to spell uXXXX escapes in
29	// the raw files written below without the escapes being decoded in this
30	// source.
31	const jsonEscape = `\`
32	
33	// escapedLookalikeKey is the same key written with the JSON escape u017f.
34	var escapedLookalikeKey = "compiled_ha" + jsonEscape + "u017f" + "h"
35	
36	// escapedUnderKey is compiled_hash with the underscore escaped.
37	var escapedUnderKey = "compiled" + jsonEscape + "u005f" + "hash"
38	
39	// rewriteBoundHashRaw replaces the committed j-bound binding field with an
40	// arbitrary raw JSON fragment, returning the damaged file content.
41	func rewriteBoundHashRaw(t *testing.T, dir, hash, fragment string) string {
42		t.Helper()
43		valid, err := readDataFile(t, dir)
44		if err != nil {
45			t.Fatal(err)
46		}
47		field := `"compiled_hash": "` + hash + `"`
48		if !strings.Contains(string(valid), field) {
49			t.Fatalf("committed file does not carry the bound field %q", field)
50		}
51		bad := strings.Replace(string(valid), field, fragment, 1)
52		writeDataFile(t, dir, []byte(bad))
53		return bad
54	}
55	
56	// assertRefusedAndUntouched opens the directory, requires the read to fail
57	// with ErrDataCorrupt naming j-bound and the binding field, and checks that
58	// the data file is still byte-for-byte bad.
59	func assertRefusedAndUntouched(t *testing.T, dir, bad string) {
60		t.Helper()
61		if _, err := Open(dir); !errors.Is(err, ErrDataCorrupt) {
62			t.Fatalf("want ErrDataCorrupt, got %v", err)
63		}
64		got, rerr := readDataFile(t, dir)
65		if rerr != nil {
66			t.Fatal(rerr)
67		}
68		if string(got) != bad {
69			t.Fatalf("open modified the damaged file")
70		}
71	}
72	
73	// A lookalike spelling alone is refused for every value shape: null (the
74	// binding-damage case), a legal hash and an explicit empty string are all
75	// corruption, never an unbound job. Writing the long s directly or escaping
