		{"direct then canonical, differing", `"` + direct + `": 2, "version": 1`},
		{"canonical then escaped, same value", `"version": 1, "` + escaped + `": 1`},
		{"escaped then ASCII variant, differing", `"` + escaped + `": 2, "VERSION": 1`},
