// named, direct or escaped.
func TestJobVersionSingleSpellingStillReads(t *testing.T) {
	directLongS := "ver" + "ſ" + "ion"
	escapedLongS := "ver" + jsonBackslash + "u017f" + "ion"
	escS := "ver" + jsonBackslash + "u0073" + "ion"
	cases := []struct {
		name string
		frag string
