		{"upper case", `"VERSION": 1`},
		{"mixed case", `"VeRsIoN": 1`},
		{"escaped letter", `"` + escS + `": 1`},
		{"direct long s", `"` + directLongS + `": 1`},
		{"escaped long s", `"` + escapedLongS + `": 1`},
